(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["kw"] = {"ui":{"skip":"Lamma dhe'n dalgh","back":"← Dehwelyans dhe AI-gile","lang.button":"Yeth: {name}","lang.dialog":"Dewis yeth","lang.search":"Hwilas yethow","lang.none":"Nyns usi yeth vyth ow kevena","lang.notYet":"Ny'n jeus {name} treylys hwath","theme.aria":"Chanjya tema: golow, tewl po du","theme.toLight":"Chanjya dhe'n tema golow","theme.toDark":"Chanjya dhe'n tema tewl","theme.toBlack":"Chanjya dhe'n tema du (du gwir, es rag skrinyow OLED)","words.underline":"Linenna yn-dann an geryow ma war an folenn","words.underlineHelp":"Gorr an logosen a-ugh ger poyntys, po y doochya, rag gweles y styr.","index.title":"AI-gile: dha vagas displegyans AI, war unn bord","index.description":"AI-gile yw bord kanban rag bagasow kodya AI. Y a oberi hag ow kweskes; ty a gav unn pil berr a dhehwelyans: tuchyow dhe dhesedha, dhe brevi ha dhe asta.","hero.logoAlt":"Ikon bord AI-gile","hero.h1.html":"Dha vagas displegyans AI, war unn&nbsp;bord.","hero.alpha":"🐣 Pre-alfa ken","hero.alphaTitle":"Abarth ha dhisplann: meur ras rag y brevi!","hero.lede":"Y a wrella hag ow kweskes. Ty a dhifun ha cafos unn pil berr: nebes govynnow, nebes taclow dhe brevi, unn diamant purpur po dew. Klyckya, asta, dehweles dhe'th kofi.","dl.windows":"Appyow Windows","dl.browser":"Gweres y'th asplyer","dl.messenger":"📱 Messenger rag dha bellgowser","dl.soon":"Skon","dl.notify":"🔔 Derivas dhymm pan wra ygeri","dl.notifySmall":"Alfa po beta","hero.secondary":"Agile, mes ny wra an bagas pesya kofi sevel nevra. (Y a wra sevel kyn fo.)","pitch.h2":"AI-gile yn kemmys geryow dell vynnydh","pitch.lede":"Dewis hirder, a unn ger bys yn 144. Pub hirder yw deskrifans y honan, skrifys rag an myns na. Tenn an slider po usya an alhwedhow seth.","pitch.rangeLabel":"Hirder yn geryow","pitch.dice":"🎲 versyon aral","pitch.words.one":"{n} ger","pitch.words.other":"{n} ger","pitch.letters.one":"{n} lytheren","pitch.letters.other":"{n} lytherennow","pitch.chars.one":"{n} arwodh","pitch.chars.other":"{n} arwodhyow","count.line.html.one":"{n} kard war an bord lemmyn","count.line.html.other":"{n} kard war an bord lemmyn","people.humans.html.one":"👥 {n} den","people.humans.html.other":"👥 {n} den","people.agents.html.one":"🤖 {n} gwithyas","people.agents.html.other":"🤖 {n} gwithyas","people.working.html.one":"⚡ {n} ow lavurya lemmyn","people.working.html.other":"⚡ {n} ow lavurya lemmyn","pre.title":"AI-gile: neppyth yw ow pos drehevys","pre.description":"Neppyth yw ow pos drehevys omma. Bord may hwra bagasow AI drehevel an pyth a wovynnydh, ha'th dhyski y'n fordh. Pre-alfa ken gans kowetha rag lemmyn.","pre.h1":"Neppyth yw ow pos drehevys omma. 🤫","pre.line":"Bord may hwra bagasow AI drehevel an pyth a wovynnydh, ha'th dhyski y'n fordh. Pre-alfa ken gans kowetha rag lemmyn.","pre.btn":"🔔 Derivas dhymm pan wra ygeri","pre.peek":"A-dryv an gweder: an bord gwir, yn fyw. Pub kartenn yw barr liwys.","pre.peekFake":"A-dryv an gweder: ottomma fatel hevel bord ow kul ober.","features.aria":"An pyth a wra","f.pile.h":"Unn pil ragos","f.pile.html":"<b>Ragos</b> a sev pup tra a'th hedh, dhyworth oll an towlow: govynnow, taclow dhe brevi, ober na yll marnas den y wul. Dha rew a lever an pyth yw nessa ha pygemmys prys a gemmer.","f.sleep.h":"Bagasow a ober hag y ow kweskes","f.sleep.p":"Pub towl a'n jeus penn ha bagas a ajentys AI. Notya war kard, ha'n bagas a dhifun, gul an ober ha'y dhri war-dhelergh gans gradhow a yll den skwith aga holya.","f.tester.h":"Prevyer AI a wra whythra a-varth","f.tester.p":"Kens es tra vyth dhe'th ri, prevyer a holyow an gradhow y'n kopi a'n app ha diskwedhes an pyth a welas, gans skeusenn skrin. Gwel an re a dremenas yn skaf hag asta gans unn klyck.","f.proof.h":"Previs, ny bromysow","f.proof.p":"Pub trosglyw a dhiskwedh an pyth a chanjyas: an fylennow, an dyffrans, an skeusennow skrin. Ny res ygeri pub app dhe wellas a yw gwrys.","f.chat.h":"Kewsel gans dha bennow","f.chat.p":"Ranna avel Discord: unn ikon rag pub towl, diamantys purpur rag an pyth a'th kas. Skriv tybyans dhe benn; ev a'n gwra kardys ha towl, gans boton ✅ Ke.","f.tidy.h":"Y honan a drus","f.tidy.p":"Kardys a-dro a dhe yn unn, titelys kemmyskys a vydh ewnhes, ha whythrans tokenys a with an kod skav. Nebes dhe gemmynna, nebes dhe dybi.","f.private.h":"Dha bos, war dha gonpoder","f.private.li1":"An bord a dheu war dha gonpoder dha honan ha ny worthyp marnas dhis.","f.private.li2":"Messajys privedh a-ugh tus yw kodys a-dhiwedh dhe dhiwedh.","f.private.li3":"Nyns eus akontys, holyoryon, na koogyow.","f.lang.h":"Yn dha yeth","f.lang.p":"Moy es 120 yeth, dhyworth Iseldiryek, Kembrek ha Japanek bys yn pirat, Yoda ha Klingon, gans chanj skav dhe Sowsnek rag geryow kreft.","f.service.h":"A-dhyworth tybyans dhe wassanaeth gwir","f.service.p":"Gwrussys neppyth gans AI a us an dus lemmyn? Merk e avel gwassanaeth ha'n bord a'th weres dh'y ressa yn ta: whythransow uptime, folen status poblek, hwarvedhow gans derivas, chanjyow a res dhedha Mos, kopiow gwith whythrys pub dydh. Gweres a dhysk pub gradh war an fordh.","msgr.h2":"AI-gile Messenger: dha bagas y'th poket","msgr.p1":"Kows gans dha bagas AI heb ygeri an bord. Kows gans pennow dha dowlow ha gans dha gowetha, ha mir orth gradhow prevyans karten ha gorthyb dhedha, oll dhyworth dha bellgowser.","msgr.p2":"Rag y junya, skan kod QR war dha vord. An kynsa prys? Keskows demo kuv a'th hembronk a-dro.","msgr.when":"Android kyns, ena versyon wiasva rag pellgowsers hag iPhone.","msgr.who":"Penn dha dowl","msgr.b1":"An ewnans rag an modh tewl yw parys. A vynn'ta an gradhow prevyans?","msgr.b2":"Mynnav, mar pleg!","msgr.b3":"1. Ygor Settyansow. 2. Dewis Tewl. Yw ewn y semlant?","tl.aria":"Linen termyn dhyworth an kensa kows bys yn an fordh a dheu","tl.h2":"Dhyworth an kensa kows bys yn an pyth a dheu","tl.lede":"Dydhyow ha prysyow gwir, yn dha gylgh termyn dha honan. Wosa hedhyw yw an towl, heb dydhyow bromysys.","tl.today":"Hedhyw","tl.planned":"towlennys","tl.cards.one":"{n} kard","tl.cards.other":"{n} kard","join.h2":"Junya ganso","join.lede":"AI-gile yw gwrys gans den koynt barvek gans AuDHD ha nebes batellyow gans yeghes brys, ha niver bras a ajentys hirwodhevus. Privedh yw lemmyn, yn alfa ken gans mikyow. A vynn the previ pan wra ygeri?","join.btn":"Rol dha dhesir","join.small":"Ni a skriv dhis dre e-bost, tra aral vyth","footer.tag":"AI-gile. Heb holyoryon, heb koogyow, heb kofi sevel.","footer.licence":"Kummyas negys","footer.status":"Studh","footer.privacy":"An pyth a withyn ni","footer.thanks":"Gelwansow dre ras ChilledChat","form.sending":"Ow tanvon…","form.failed":"Ny worras: assay arta war-lergh.","form.offline":"Ny yllyn dhe dhos dhe AI-gile: assay arta war-lergh.","form.keep":"Ny'n usyn marnas rag gorthybi dhis, ha wosa henna ni a'n dilea. Heb holyoryon, heb koogyow.","form.keepLink":"An pyth a withyn ni","interest.title":"AI-gile: derivas dhymm pan wra an alfa ygeri","interest.description":"Gasa dha e-bost rag klywes pan wra alfa po beta ken AI-gile ygeri.","interest.h1":"🔔 Derivas dhymm pan wra ygeri","interest.lede":"AI-gile a'n jeus pre-alfa ken. Gasa dha e-bost ha ni a skrif unn tro, pan vo spas dhis.","interest.email":"Dha e-bost","interest.which":"Pyth prov?","interest.alpha":"Alfa ken: abarth, kales, lies chanj","interest.beta":"Beta: moy cadarn, war-lergh","interest.both":"Nep onan, pynag a dheu kensa","interest.submit":"Gorr vy war an rol","interest.thanks":"Meur ras! Ty yw war an rol.","licence.title":"AI-gile: kummyas negys","licence.description":"A usyydh ty AI-gile y'th negys? Kemmer kummyas negys heb pris.","licence.h1":"📜 Kummyas negys","licence.lede":"A usyydh ty AI-gile orth dha ober? Derivas dhyn pyw os ha pyth a wredh. Mar kwra nebes da, an kummyas yw heb pris.","licence.company":"Kowethas","licence.website":"Gwiasva","licence.what":"Pyth a wredh","licence.how":"Fatel weres an bys","licence.email":"E-bost","licence.submit":"Peyna","licence.thanks":"Meur ras! Ni a worthyp dre e-bost.","status.title":"Studh AI-gile","status.h1":"Studh AI-gile","status.quiet":"Pub tra yn kosoleth","status.intro":"Yw AI-gile ow oberi lemmyn? An folenn ma a wra whythra an wiasva, kevrenna bordow, galwansow ha'n iskargans pub 5 mynysenn.","status.up":"Ow oberi (gorthebys yn {ms} ms)","status.slow":"Ny worthybis an whythrans diwettha, ow assaya arta","status.down":"Ny oberi: ny worthybis an dhew whythrans diwettha","status.svc.web":"Gwiasva","status.svc.web.offers":"An wiasva ma: pyth yw AI-gile, ha'n furvlen diddordeb","status.svc.boards":"Kevrenna bordow","status.svc.boards.offers":"Bordow poblek, messajys yntra kowetho ha gelwansow","status.svc.calls":"Galwansow","status.svc.calls.offers":"Lev, video ha kevrenna skrin yn AI-gile","status.svc.download":"Iskargans","status.svc.download.offers":"An daffar-ynstallya Windows ha kevrennow gelwel","status.checking":"Ow whythra…","status.offline":"Ny yllir dos dhe wrians an studh lemmyn (ow assaya arta)","status.updated":"nowedhys {ago}","status.justNow":"hepkoryans","status.min":"{n} mynysenn alena","status.hours":"{n} our alena","status.days":"{n} dydh alena","privacy.title":"AI-gile: an pyth a withyn ni","privacy.h1":"An pyth a withyn ni","privacy.lede":"Yn berr: an pyth a dhannvonydh dhyn hepken, ha na pell.","privacy.only":"An pyth a dhannvonydh dhyn hepken: an pyth a skrifydh yn furvlen, kepar ha'th ebost. Travyth aral a-dro dhis.","privacy.sealed":"Selys yw ma na yll agan servell y redya: y'th peurell kyns ev dhe dhiberth (war beurell kottha, an very prys may teu). Agan bord agan honan hepken a yll y igeri.","privacy.server":"Dileys yw a'n servell kettell dhrehedh agan bord. Pypynag a vo ena hwath wosa 30 dydh a vydh dileys bytegyns.","privacy.board":"Ni a'n gwith war agan bord hepken bys pan wren ni gorthybi dhis, ena ni a'n dilea ena ynwedh.","privacy.none":"Heb holyoryon, heb koogyow, heb dielvennans.","privacy.local":"Dha yeth ha'th dewis golow po tewl a drig y'th peurell dha honan. Ny vydhons i danvenys dhyn nevra.","privacy.ask":"Y fynnydh y vos gyllys kyns? Gorthyp dh'agan ebost ha lavar yndella.","live.h2":"Golyewgh ev ow ben drehevys, yn fyw","live.caption":"Pub kartenn yw kudhys: hwi a wel furv an oberyow, nyns yw an geryow.","live.watching.one":"yn fyw: {n} ow kolyewi","live.watching.other":"yn fyw: {n} ow kolyewi","live.last.now":"An kard dhiwettha a veu removys poran lemmyn","live.last.min.one":"An kard dhiwettha a veu removys {n} mynysen alebma","live.last.min.other":"An kard dhiwettha a veu removys {n} mynysen alebma","live.last.hour.one":"An kard dhiwettha a veu removys {n} our alebma","live.last.hour.other":"An kard dhiwettha a veu removys {n} our alebma","live.last.day.one":"An kard dhiwettha a veu removys {n} dydh alebma","live.last.day.other":"An kard dhiwettha a veu removys {n} dydh alebma","live.offline":"An bord yn fyw a gemmer sesyans byghan. Dewgh arta a-berth hir.","live.cols":"Backlog|Dhe wul|Yn hwel|An bagas ow whythra|Rag ty dhe testya|Rag an bagas|Gwrys"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Delegys."]},{"n":2,"texts":["Kanban robots.","Ajentys, ordenys.","Tybyansow, gwrys."]},{"n":3,"texts":["Kanban rag robots.","Tybyansow a dheu gwryansow.","Kanban ajentys, heb pris."]},{"n":5,"texts":["Bord kanban dhyworth ajentys gorrys.","Ty a skriv. Ajentys a wrella.","Heb pris, lokel, previs, nebes gokki."]},{"n":8,"texts":["Bord kanban heb pris ma ajentys AI a ober ynno.","Skriv tybyans. Ajentys a'n gwra. Ty a'n asta.","Agile rag unn den ha lies robot a dal."]},{"n":13,"texts":["Bord kanban war dha gonpoder, ajentys AI ow kemmer kardys, ty an penn.","Skriv tybyans. Bagas a ajentys a'n gwra. Prevyer a'n whythra. Ty a lever eth.","Heb akontys, heb holyoryon: bord, nebes robots, ha ty yw an gwarden."]},{"n":21,"texts":["AI-gile yw bord kanban rag ober gans ajentys kodya AI. Y a gemmer an kardys; ty a'ga previ hag a'ga asta.","Pub towl a gav penn ha bagas a ajentys AI. Notya war onan vyth a'n kardys, ha'n bagas a dhallath ober.","Bord a oberow personek heb pris, ow tos war dha gonpoder dha honan. An oberoryon yw robots. An den a lever eth yw ty."]},{"n":34,"texts":["Ty a worr tybyansow war an bord. Bagas a ajentys AI a'ga gwra gwryansow a ober, a'ga prov, ha'ga dri war-dhelergh gans gradhow dhe asaya. Nyns yw tra vyth gwrys erna lever ty.","AI-gile yw bord kanban gwrys y'n chi a wrug Rich gans gweres bras a'n ajentys a wra ev lywya lemmyn. Heb pris yw, ow tos war dha gonpoder ha kevrennys gans mikyow, ny'n gwerthir.","Gwel bord kanban kemmyn, gans colonnow dhyworth Backlog bys yn Done, marnas ajentys AI a gemmer an kardys. Y a wra derivas aga fordh, govyn pan vons stak, ha gortos pup prys dha vawl wartha."]},{"n":55,"texts":["AI-gile yw bord kanban le may ma an bagas gwrys a ajentys AI. Pub towl a'n jeus penn a wra towl an ober, ha gweresoryon a'n gwra. Pan yw parys an gwryans, prevyer AI a'n prov hag a gemmer skeusenn skrin, ena ev a dheu dhe'th pil. Asta ev, po notya, ha'n bagas a wra arta.","Dallath a wrug dre unn den a vynna holya lies sesyon kodya AI war unn prys, ha tevi a wrug dhe bord gwir. A dheu war dha gonpoder, ny'n jeus res a akont, ha nyns eus holyoryon. Heb pris yw rag mikyow ha tus a'n jeus hwans. Nyns yw gorfednys hwath, ytho gwayt bleydhow kales ha taclow dyannedhys.","Ottomma an versyon wir. Res yw dhis hwath kavos an tybyansow, ha res yw dhis hwath whythra an dyvres. An pyth a wra AI-gile yw pub tra yn-dann: ev a with an kardys yn ordyr, a dhifun an ajent ewn pan wredh notya, a dhiskwedh poran an pyth a chanjyas, hag a'n kuntell oll yn unn pil berr ragos."]},{"n":89,"texts":["AI-gile yw bord kanban heb pris a dheu war dha gonpoder dha honan. Yn le tus, pub towl a'n jeus bagas a ajentys AI: penn a wra dha dybyansow kardys ha towl, ha gweresoryon a gemmer an kardys herwydh poos. Pan yw tra gwrys, prevyer AI a holya gradhow an previ hag a dhiskwedh an pyth a welas. Ena ev a wayt yn unn pil henwys Ragos. Ty a'n asta, po notya, ha'n bagas a assay arta. Nyns usi tra vyth ow tos dhe Done hebdhos.","Nebes tuchyow na wayt ty martesen. Golvan nos a with an golonn Dhe wul leun hag ty ow kweskes, ow tewis kardys na wra whansa gorthyp dhyworth dhis. Kontyer tokenys a dhiskwedh pygemmys a wrug an ajentys usya hedhyw ha'n seythun ma, ha No Token Mode a lever dhedha hedhi. Ty a yll skrifa dhe vikyow, ha messajys privedh yw kodys a-dhiwedh dhe dhiwedh. An bord a gews dro dhe 120 yeth, Iseldiryek, Flemmyk, pirat ha Klingon ynna. Nyns yw tra vyth anodho pris, ha nyns eus den ow whilas y werthi dhis.","AI-gile yw towl byghan personek, nyns yw kowethas. Rich a vynna gwitha lies towl kodya AI heb ygeri pub app dhe wellas, ytho ev hag an ajentys a wrug bord rag hedna, ena ev a usyas an bord dhe wul an remnant anodho y honan. Yma yn pre-alfa ken, hag a wra ober, an brassa rann, rag nebes mikyow. Nyns eus folen prisyow, lyther-nowodhow na towl kressya. Mar hevel ev da dhis, ty a yll govyn pan wra ygeri nebes moy dhe'y brevi."]},{"n":144,"texts":["AI-gile yw bord kanban rag unn den ha lies ajent AI. A dheu war dha gonpoder dha honan hag yw heb pris yn tien. Ty a worr towlow, ha pub towl a gav penn ha bagas byghan. Ty a gows gans an penn, nebes avel Discord, ha deskrifa tybyans; an penn a'n gwra kardys ha towl, ena ev a wayt erna wrello ty wul Ke. An bagas a oberi dre an kardys herwydh poos, dre linen gomment sempel gwrys rag modellow yeth. Kens es tra vyth dhe dhehweles dhis, prevyer AI a holya an gradhow y'n kopi a'n app hag a worr skeusenn skrin. Ober gorfednys a dheu dhe'th pil gans an fylennow chanjys ha'n dyffrans. Ty a'n asta, po gasa notya, ha'n bagas a dhifun hag assaya arta. Yn unnik ty a yll gorra kard dhe Done. Oll hemma a dheu war dha gonpoder, heb akontys, heb holyoryon, heb koogyow.","Dydh gans AI-gile, a-dro. Der an gordhuwher ty a asa nebes notyow: an boton ma yw yn le kamm, an rol na a res bos ordenys, a yllyn kavos tema tewl. Ty a dhe dhe gwetha. An ajentys a red an notyow, gul an chanjyow, aga previ hag aga dri dhis arta. Mars yw gwag Dhe wul, an golvan nos a'n leun dhyworth an backlog gans kardys na wra whansa gorthyp dhyworth dhis. Y'n myttin yma unn pil berr: dew wovynn ha nebes taclow dhe brevi, pub onan gans gradhow a yll den kyskus aga holya ha skeusenn skrin ow tiskwedhes y fia ober. Ty a glyck dre oll, asta an re dha ha danvon an remnant war-dhelergh. Kontyer tokenys a dhiskwedh pyth a wrug oll hemma usya, ha No Token Mode yw rag seythunyow tynn. Ena ty a dhebry dha vyttin, na yll an ajentys gweres ynny hwath.","A-varth, an pyth nyns yw AI-gile. Nyns yw startup, ny'n gwerthir, ha nyns eus den ow kuntell dha dhata. Bord heb pris yw a dheu war dha gonpoder, heb akontys, heb holyoryon, heb koogyow. An pyth yw: unn le kemmys ordenys dhe weles pub towl kodya AI warbarth, gans bagas a ajentys ow ober an kardys ha ty ow tesedha. Ev a gelmy kardys a-dro, ewnhe titelys kemmyskys, ha gwitha golvan dhe bell may kemmer an kod skav. A gews dro dhe 120 yeth, dhyworth Iseldiryek ha Flemmyk bys yn pirat ha Klingon. Mikyow a yll skrifa an eyl dhe'n gela, yn privedh ha kodys. Gwrys veu gans Rich ha niver bras a ajentys a dhal, an brassa rann ow usya y honan. Yma yn pre-alfa ken, ytho kales yw yn nebes plasow. Mar tykki ev hwek, pys yn ewn, ha martesen ty a dheu yn abarth."]}],"quips":{"1":"Unn ger. Bold. Martesen re vold.","3":"Tri ger. Kens onest es an brassa rann a folennow produkt.","8":"Eth ger. Hwath berrach es sevel.","21":"An hirderow yw poyntys hwedhel, dre an fordh. Yn sur y'ns y.","55":"Pymp ha hanter-kans ger. Dew gard a veu gorfednys ha ty ow redya.","144":"Hemma yw an hirra. Nyns eus 233. An ajentys eth dhe gwetha."}},"timeline":{"first-idea.name":"An kensa tybyans","first-idea.line":"An kensa kows a-barth, kens bos kod vyth.","first-board.name":"An kensa bord","first-board.line":"Bord a wra holya y wrians y honan: kardys, colonnow, tenna ha gasa, towlow.","team-roles.name":"Bagas ha rolys","team-roles.line":"Profilys ajent, skantlynnow bagas, spasow ha pyw a wra pyth.","install.name":"Staliyans ha dyllansow","install.line":"Zip a yll mik staliya, nowedhyansow y honan, kanalys ha dehweles.","usage-saver.name":"Gwitha usadow","usage-saver.line":"Musur pygemmys a gost an gweresow, gwitha an kod skav, sawya dha finweth.","friends.name":"Mikyow ha kevrenna","friends.line":"DMs privedh, relay kodys, gelwyansow, rolys ha towlow kevrennys.","languages.name":"Yethow","languages.line":"Pub tekst skrin yn fylen yeth, gans Iseldiryek ha Flemmyk a-gensa.","ai-tester.name":"Prevyer AI","ai-tester.line":"Prevyer a wra whythra pub trosglyw a-varth ha diskwedhes an pyth a welas.","website.name":"An wiasva","website.line":"aigile.lol, an teaser ha'n linen termyn ma.","streaming.name":"Kows ha ruth","streaming.line":"Discord, Twitch, OBS, modh streamer, GIFs ha emojis.","no-ai.name":"Dyllans heb AI","no-ai.line":"Bord rag tus a godh heb AI, ha bordys poblek.","night-watch.name":"Golvan nos","night-watch.line":"Golvaner ha Scrum Master a with an bagasow orth ober hag y ow kweskes.","p-more.name":"Pub tra aral","p-more.line":"Tybyansow byghan a'n jeus gwayt aga thro.","p-android.name":"Pellgowser ha Android","p-android.line":"Delivrans dha bord dhyworth pellgowser, wosa hedna app Android dhedhyek.","p-release.name":"Alfa ha pella","p-release.line":"Alfa ken, an wiasva bew, wosa hedna beta.","p-languages.name":"Moy a yethow","p-languages.line":"Moy es kans yeth, ha modh sedhek rag deskadoryon.","p-engines.name":"Moy a jynnys AI","p-engines.line":"Dewis Claude, Codex po Gemini rag pub ajent.","p-pro.name":"Usadow a'n pyskessa","p-pro.line":"Lavryow ryskys, yettys junyans, kardys happyans ha gwithysi.","p-self.name":"Gwitha ahanas","p-self.line":"Modh skwith, memorys a woeth a'th honan ha 4:20.","p-servers.name":"Servyoryon ha kressya","p-servers.line":"Settyansow servyer glasel, rolys ha towl rag kressya.","p-livestream.name":"Ekstras ruth","p-livestream.line":"Kows Twitch, emojis dhedhyek ha gwel bew poblek."},"words":{"button":"📖 Geryow kreft","h":"📖 Geryow displegys","intro":"An geryow a vetydh yn AI-gile, yn geryow sempel: y wul, y janjya yn sur, y witha ow keskerdhes rag an dus a'n us, hag oberi avel bagas gans AI.","search":"Hwilas ger…","none":"Nyns eus ger a dhesedh.","close":"Degea","count":{"one":"{count} ger","other":"{count} geryow"},"groups":[{"id":"build","name":"🛠️ Y wul"},{"id":"change","name":"🔀 Y janjya yn sur"},{"id":"run","name":"🛎️ Ow ressa gwassanaeth"},{"id":"team","name":"🤝 Oberi avel bagas (ha gans AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Fylder kod an towl ha'y istori leun a commits, menowgh gwithys ynwedh war GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Linenn dyberth a oberow y'n kod, may hyller gul chanjyow heb tüchya an ver wyr.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Skeusen withys a'n kod, gans notya berr a'n pyth a gemmis. Ty a yll mos dhe unn pup prys.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Danvon skeusennow withys (commits) dhyworth an kombyuter ma dhe GitHub, may fons kopyys ha kevrennys."},{"id":"merge","g":"build","word":"Merge","text":"Junya chanjyow branch dhe'n ver wyr arta."},{"id":"pr","g":"build","word":"Pull request","text":"Govyn may fo chanjyow branch gwithrys ha junys dhe'n ver wyr.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Kerhes an kod heb chanjya pyth a wra: restrennow byghanna, hanow splan, nebes daskedhes."},{"id":"bug","g":"build","word":"Bug","text":"Neppyth na wra kepar ha dell dalvia.","also":["bugs"]},{"id":"test","g":"build","word":"Previ","text":"Assaya darn gorfennys a oberow rag gwithra ev dhe wul an pyth a veu govynnys, a-ragh y assentya.","also":["tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Berrheans a quality assurance (surheans kwalita): an whythransow awtomatek a ober kyns ès tra vyth dhe vos yn fyw. Pan vo QA rudh, neppyth a fyllis, ha ny yll mos yn fyw bys pan vo amendys.","also":["whythrans kwalita","quality assurance"]},{"id":"deploy","g":"change","word":"Deploy","text":"Gorra ver nowydh yn fyw, rag ensampel war servyer may hwra tus y usya."},{"id":"release","g":"change","word":"Dascorenn","text":"Fardel henwys a ober gorfennys a ya yn fyw warbarth, gans notennow berr a'n pyth a janjyas. 🚀 Dascorennow a skrif an notennow dhyworth an kardys gorfennys.","also":["dascorennow","release"]},{"id":"rollback","g":"change","word":"Dehwel","text":"Mos war-dhelergh dhe'n diwettha versyon a oberas, pan wra versyon nowydh ankombrynsi. Yn AI-gile y wra rol-wiryans dhyworth an gradhow diswul skrifys war pub chanj.","also":["rollback","roll back","dehwelys"]},{"id":"live","g":"change","word":"Yn fyw","text":"An versyon gwir a us an dus, yn le kopi rag assaya traow. Displegyoryon a'n gelow production ynwedh.","also":["live","production"],"noTip":1},{"id":"change","g":"change","word":"Chanj","text":"Chanj towlennys dhe neppyth may trest an dus warnodho, skrifys kyns oll: pyth, prag, an peryl, pan, ha fatell y diswul. Dalleth onan gans 🔀 Drehedhes chanj.","also":["chanjyow","govyn chanj","change request"],"noTip":1},{"id":"risk","g":"change","word":"Peryl","text":"Neppyth a yll mos yn kamm, merkys herwydh pes gwiryon yw ha pes drog via. ⚠️ Perylyow a's gwith yn unn rol, an merk ughella kynsa, pub onan gans dydh dhe vires arta.","also":["perylyow","kovskrif perylyow"]},{"id":"chgwin","g":"change","word":"Fenester chanj","text":"An prysyow may hyll chanjyow mos yn fyw, rag ensampel gorthugher kosel dy' Meurth. A-ves dhe fenester ny yll kard chanj bos gorfennys, marnas yth yw dyffrans.","also":["fenestrys chanj","change window"]},{"id":"gonogo","g":"change","word":"Mos / na vos","text":"Raglev uskis kyns ès chanj dhe vos yn fyw: pub den a res dhodho bennyga a lever Mos po Na vos. Ny ya yn rag marnas pan vons i unnver.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Fowes","text":"Gortos \"ya\" kyns ès an ober dhe dhalleth. Kard drehedhys gans koweth, po chanj, a hortos yn ✅ Fowesow bys pan wrylli y aswon po y nagha.","also":["fowesow","approval"]},{"id":"quiettime","g":"change","word":"Prys kosel","text":"Termyn, avel fros, diskwedhyans po an nos, ma na ya travyth yn fyw. An bagasow a bes ow oberi hag ow previ, mes mos yn fyw a hortos bys y worfen. Yn leow erell y'n gelwir change freeze.","also":["prysyow kosel","change freeze"]},{"id":"service","g":"run","word":"Gwassanaeth","text":"Neppyth a wrussys may trest an dus warnodho, avel gwiasva po app, gwithys may pesso ow oberi. Merk \"Gwassanaeth yw an towl ma\" ha lavar pyth a brof, piw a'n us ha piw yw yn galow.","also":["gwassanaethow","service"]},{"id":"uptime","g":"run","word":"Whythrans uptime","text":"Whythrans awtomatek, pub nebes mynysennow, bos dha wassanaeth hwath ow korthybi. Mar fyll lies treveth war-rag, AI-gile a wra ygeri kard hwarvedh y honan.","also":["uptime","whythransow uptime"]},{"id":"statuspage","g":"run","word":"Folen status","text":"Folen poblek a dhiskwedh mars yw gwassanaeth ow oberi (gwyrdh, rudhvelyn po rudh) gans an nowodhow diwettha, may hyllo an dus a'n us mires ena yn le govyn.","also":["folennow status","status page"]},{"id":"incident","g":"run","word":"Hwarvedh","text":"Neppyth yw terrys rag an dus a'n us lemmyn, avel an wiasva dhe vos dhe ves. Kard 🔥 hwarvedh a lamm dres an lost: y wul dhe oberi arta a dheu kynsa.","also":["hwarvos drog","hwarvedhow","incident"]},{"id":"major","g":"run","word":"Hwarvedh bras","text":"Hwarvedh meur: lies den tochys, po mona po data yn peryl. Unn boton a worr pub bagas warnodho (swarm), a dhifun an den yn galow hag a wovyn nowodhow status pub 30 mynysen.","also":["hwarvedhow bras","major incident"]},{"id":"oncall","g":"run","word":"Yn galow","text":"Bos an den a worthyb pan dorr neppyth, yn nos kyn fo. Pub gwassanaeth a'n jeves esel bagas yn galow, ha'n esel na yw dihunys kynsa rag y hwarvedhow.","also":["on call","on-call"]},{"id":"replyby","g":"run","word":"Termyn gorthyp","text":"Pes hir a yll kard gortos an kynsa gorthyp, rag ensampel unn our rag hwarvedh. Wosa henna y'n jeves klock rudh, ma na vo travyth ankevys yn kosel. Henwys amkan gorthyp ynwedh.","also":["termynyow gorthyp","amkan gorthyp","response target"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Golok verr war-dhelergh wosa hwarvedh: pyth a hwarva, pyth a weresas ha pyth dhe janjya, heb blamya denvyth. Ny yll hwarvedh bos degeys hebdho.","also":["post-mortem","postmortem","dasweles wosa hwarvedh"]},{"id":"problem","g":"run","word":"Kesyow","text":"An acheson kudh a-dryv onan po moy a hwarvedhow. Kard 🧩 kesyow a guntell hwarvedhow a dheu arta hag arta, may fo an acheson kevys hag amendys rag nevra.","also":["kudyn","kudynnow","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Gwreydh acheson","text":"An gwir reson a dorras neppyth, a-der an pyth a welsys ow mos yn kamm hepken. Amend an gwreydh acheson ha'n hwarvedh a hedh a dhos arta.","also":["root cause"]},{"id":"workaround","g":"run","word":"Fordh a-dro","text":"Fordh dhe witha traow ow oberi bys pan vo an gwir amendyans parys, avel dalleth neppyth arta pan vo sygys. Skrifys yw war an kard kesyow ma na res dhe dhenvyth y gavos arta.","also":["fordhow a-dro","workaround","remedi"]},{"id":"knownerror","g":"run","word":"Kamm godhvedhys","text":"Kesyow mayth yw konvedhys an acheson hag a'n jeves fordh a-dro, mes nag yw amendys hwath. 🧩 Kammow godhvedhys a's rol, may hwrello pubonan usya an fordh a-dro yn le palas arta.","also":["kammow godhvedhys","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Kevarwodhyow gam ha gam rag amendya sort godhvedhys a ankombrynsi, may fo gwrys an keth fordh, yn uskis, pub treveth. Wosa hwarvedh bras an bagas a yll profya onan rag dha OK.","also":["runbook","runbooks"]},{"id":"backup","g":"run","word":"Kopi gwith","text":"Kopi gwithys a'th data a-dhia kyns, dhe drelya dhodho mar pydh neppyth kellys po shyndys. AI-gile a wra kopi gwith a'th bordys pub dydh.","also":["kopiow gwith","kopia","backup"]},{"id":"restore","g":"run","word":"Daskorra","text":"Gorra data war-dhelergh dhyworth kopi gwith. Ny vern kopi gwith yn hwir marnas pan wodhes y hyll bos daskorrys, ytho talvos yw y assaya treweythyow.","also":["daskorrys","restore"]},{"id":"backlog","g":"team","word":"Backlog","text":"Tybyansow hag oberow na vo towlennys hwath. Ny vydh gwrys tra ena erna vo movys dhe Dhe wul."},{"id":"sprint","g":"team","word":"Sprint","text":"Termyn berr a oberow (menowgh unn seythun po dew) gans set ervys a gardys dhe worfenna.","also":["sprints"]},{"id":"standup","g":"team","word":"Kuntelles sav","text":"Kwithra skyff: pyth a wrug pub esel an bagas, pyth a wra nessa, ha pyth a'n lett.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Bord gans kolonnow (Dhe wul, Yn hwel, Gwrys) may tefons kardys a-gledh dhe'n dyhow ha'n oberow ow hwarvos."},{"id":"wip","g":"team","word":"Finweth WIP","text":"Oberow yn hwel: an moyha kardys a dal kolonn synsi, may whorfenno an bagas taklow a-ragh dallath moy.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"Rol-wiryans berr an bagas a styr \"gorfennys\", avel previs ha displegys, kyns ès kard dhe vos res dhis. Y ewl, an Definition of Ready, a lever pan yw kard kler lowr dhe dhalleth.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Pentewer previ","text":"An kardys gorfennys ow kortos may hwrylli aga assaya, onan wosa y gila. Aswon onan po y dhanvon war-dhelergh gans noten, ha'n nessa a dheu.","also":["pentewryow previ","test pile"]},{"id":"retro","g":"team","word":"Dasselyans","text":"Golok war-dhelergh war fatell ober an bagas, dhe vos unnver war unn dra dhe wul gwell. Yn AI-gile dasselyans a brof chanj dhe fordhow oberi an bagas, ha ty a lever Mos po Na hwath.","also":["retro","retrospective"]},{"id":"peerreview","g":"team","word":"Whythrans a-dhyworth par","text":"Dewlagas moy: AI aral a whyther ober pub kard kyns ès y dhos dhis, ma'n gallo le a gammow tremena.","also":["peer review","code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"Pubonan dhe'n ober: pub bagas a as ober aral dhe weres unn towl a vern bys pan vo dyghtys. Towlow erell a hortos y'n kettermyn.","also":["swarm","swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"An den a with an ober ow resek: ev a verk kardys sygys, a bok an bagasow hag a'th perth kov a'n pyth ow kortos. Yn AI-gile an Penn Scrum Master a wra henna dres pub towl.","also":["Penn Scrum Master","Lead Scrum Master"]},{"id":"agent","g":"team","word":"Ajent","text":"AI a oberi dhe-honan war dasek: a redya an kod, a wra chanjyow, a ren gwithransow, ha dos gans derivas.","also":["agents"]},{"id":"token","g":"team","word":"Token","text":"An unita may fo devnydh AI nivrys: ogas dhe nebes lytherennow a dhekst redys po skrifys. Nebes tokens, moy a'th towl gesys.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Gorhemmyn byghan a ren dre honan orth prys ervys, y.h. pan dhallath sesyon AI, may klywo an bagas dha notyow.","also":["hooks"]}]}};
